/**
 * The three required retrieval queries reproduce the published scores in
 * docs/mcp_retrieval_tests.md (first generated by the Python implementation).
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

import { pyJsonDumps } from "../scripts/retrieval-demo.ts";
import { BillingIndex } from "../src/indexer.ts";
import { search } from "../src/server.ts";

const GOLDEN: Record<string, [reference: string, score: number][]> = {
  "extra internet price": [
    ["§8.1 What is the cost of extra internet?", 7.043],
    ["§3.2 Additional internet blocks", 5.821],
    ["§2.2 Additional minutes", 4.431],
  ],
  "partial payment rules": [
    ["§5.1 Full and partial payments", 7.854],
    ["§8.2 Why is my bill higher this month?", 2.918],
    ["§5.2 Payment confirmation", 2.425],
  ],
  "late payment penalty": [
    ["§6.2 Late payment reminder", 7.16],
    ["§6.1 Due date", 3.536],
    ["§6.3 Service restriction", 3.323],
  ],
};

const DOC = fileURLToPath(new URL("../../docs/mcp_retrieval_tests.md", import.meta.url));

type Published = { rows: [string, number][]; json: string };

/** Per query in the doc: its ranking table and its raw JSON block. */
function parseDoc(markdown: string): Map<string, Published> {
  const out = new Map<string, Published>();
  const sections = markdown.replaceAll("\r\n", "\n").split(/^## \d+\. /m).slice(1);
  for (const section of sections) {
    const query = /^`([^`]+)`/.exec(section)![1]!;
    const rows = [...section.matchAll(/^\| \d+ \| (.+) \| ([\d.]+) \|$/gm)].map((m): [string, number] => [m[1]!, Number(m[2])]);
    const json = /```json\n([\s\S]*?)\n```/.exec(section)![1]!;
    out.set(query, { rows, json });
  }
  return out;
}

const index = BillingIndex.fromFile();
const doc = parseDoc(readFileSync(DOC, "utf-8"));

describe("golden retrieval scores", () => {
  it.each(Object.entries(GOLDEN))("%s ranks and scores as published", (query, expected) => {
    const result = search(index, query);
    expect(result.matches.map((m) => [m.reference, m.score])).toEqual(expected);
  });

  it.each(Object.keys(GOLDEN))("docs/mcp_retrieval_tests.md agrees with the server for %s", (query) => {
    const published = doc.get(query)!;
    expect(published.rows).toEqual(GOLDEN[query]);
    expect(published.json).toBe(pyJsonDumps(search(index, query)));
  });
});
